"""Fast build gate; full row comparisons are generated by the conversion/QA tools."""
from hashlib import sha256
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]

def digest(path):
    with path.open('rb') as stream:
        check=sha256()
        for block in iter(lambda:stream.read(1024*1024),b''):
            check.update(block)
        return check.hexdigest()

def check_assets():
    path=ROOT/'app/src/main/assets/content/manifest.json'
    manifest=json.loads(path.read_text(encoding='utf-8'))
    assert manifest==json.loads((ROOT/'data/manifests/content-packages.json').read_text(encoding='utf-8')),'Asset manifest differs from verified output'
    assert set(manifest['packages'])=={'fr','es'},'Unexpected formal target languages'
    assert manifest['schema_sha256']==digest(ROOT/'schemas/content-v1.sql'),'Schema changed; regenerate and verify packages'
    for target,row in manifest['packages'].items():
        asset=(ROOT/'app/src/main/assets'/row['asset']).resolve()
        assert asset.is_relative_to(ROOT/'app/src/main/assets/content'),'Invalid asset path'
        expected=row['sha256']
        assert digest(asset)==expected and asset.stat().st_size==row['bytes'],'Packaged content differs from manifest'
        assert digest(ROOT/'data/content-packages'/f'{target}.db')==expected,'Canonical package differs from manifest'
        assert digest(ROOT/'data/source-snapshots'/row['source_file'])==row['source_db_sha256']==row['content_version'],'Formal source identity changed'
        assert digest(ROOT/'data/normalized'/f'{target}.content-v1.json')==row['intermediate_sha256'],'Normalized input differs from manifest'
        report=json.loads((ROOT/'docs/qa/p4'/f'{target}-content-diff.json').read_text(encoding='utf-8'))
        assert report['passed'] and report['package_sha256']==expected and report['source_sha256']==row['source_db_sha256'],'Full content verification missing or stale'
        print(f'{target}: unified package, formal source and full comparison hashes match')
    for name,row in manifest['licenses'].items():
        assert digest(ROOT/'app/src/main/assets/licenses'/name)==row['sha256'],'License notice changed'
    assert not any((ROOT/'app/src/main/assets'/name).exists() for name in ['french_content.db','spanish_content.db']),'Legacy copies must remain frozen inputs, not runtime assets'
    return manifest

if __name__=='__main__':
    check_assets()
